<?php
require __DIR__.'/lib/lms.php';require __DIR__.'/lib/school.php';$t=require_login();$id=(int)($_GET['class']??$_POST['class_id']??0);$c=$id?family_class($id):null; // chủ lớp hoặc GV chủ nhiệm
if($_SERVER['REQUEST_METHOD']==='POST')try{
 if(!$c)throw new RuntimeException('Chọn lớp.');
 if(($_POST['action']??'')==='grade_level'){$grade=(int)($_POST['grade_level']??0);if($grade<1||$grade>12)throw new RuntimeException('Khối lớp từ 1 đến 12.');q('UPDATE classes SET grade_level=? WHERE id=?',[$grade,$id]);redirect('family.php?class='.$id);}
 $code=trim($_POST['student_code']??'');if(!$code||!qv('SELECT 1 FROM students WHERE class_id=? AND student_code=?',[$id,$code]))throw new RuntimeException('Học sinh phải có mã và thuộc lớp.');
 if(($_POST['action']??'')==='invite'){$token=bin2hex(random_bytes(16));q('INSERT INTO parent_invites(class_id,student_code,token_hash,expires_at) VALUES(?,?,?,NOW()+INTERVAL 7 DAY)',[$id,$code,hash('sha256',$token)]);$_SESSION['parent_invite_once']=$token;flash('Mã mời dùng một lần, hiệu lực 7 ngày. Gửi riêng cho phụ huynh đúng học sinh.');}
 elseif($_POST['action']==='comment')q('INSERT INTO teacher_comments(class_id,student_code,teacher_id,comment) VALUES(?,?,?,?)',[$id,$code,$t['id'],required_text('comment',10000)]);
 elseif($_POST['action']==='revoke')q('DELETE FROM parent_links WHERE class_id=? AND student_code=? AND parent_id=?',[$id,$code,(int)$_POST['parent_id']]);else throw new RuntimeException('Lệnh không hợp lệ.');redirect('family.php?class='.$id);
}catch(Throwable $e){flash($e->getMessage(),'bad');}
page_head('Phụ huynh và nhận xét','family.php');echo '<h1>Phụ huynh và nhận xét</h1><form method="get"><select name="class">';foreach(family_classes() as $r)echo '<option value="'.$r['id'].'" '.($id===$r['id']?'selected':'').'>'.h($r['name']).'</option>';echo '</select><button>Chọn lớp</button></form>';
if(isset($_SESSION['parent_invite_once'])){echo '<div class="card"><b>Mã mời:</b> <code>'.h($_SESSION['parent_invite_once']).'</code></div>';unset($_SESSION['parent_invite_once']);}
if($c){echo '<form method="post" class="card stack">'.csrf_field().'<input type="hidden" name="class_id" value="'.$id.'"><label>Học sinh<select name="student_code">';foreach(qall('SELECT * FROM students WHERE class_id=? AND student_code IS NOT NULL AND student_code<>""',[$id]) as $r)echo '<option value="'.h($r['student_code']).'">'.h($r['full_name'].' · '.$r['student_code']).'</option>';echo '</select></label><label>Khối lớp (cho gợi ý AI)<input name="grade_level" type="number" min="1" max="12" value="'.$c['grade_level'].'"></label><button name="action" value="grade_level">Lưu khối lớp</button><label>Nhận xét<textarea name="comment"></textarea></label><div><button name="action" value="comment">Lưu nhận xét cho phụ huynh</button> <button name="action" value="invite">Tạo mã mời phụ huynh</button></div></form>';
 foreach(qall('SELECT l.*,p.full_name FROM parent_links l JOIN parents p ON p.id=l.parent_id WHERE l.class_id=?',[$id]) as $r)echo '<form method="post">'.csrf_field().'<input type="hidden" name="class_id" value="'.$id.'"><input type="hidden" name="student_code" value="'.h($r['student_code']).'"><input type="hidden" name="parent_id" value="'.$r['parent_id'].'">'.h($r['full_name'].' ↔ '.$r['student_code']).' <button name="action" value="revoke">Thu hồi liên kết</button></form>';
}page_foot();
